result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "ttt.py", "content": """"Unbeatable tic-tac-toe engine.

Board representation: a 9-tuple of "X", "O" or " " (index 0..8, row-major).

Search:
- ``minimax``    -- plain minimax, returns (score, best_move).
- ``alphabeta``  -- minimax with alpha-beta pruning, returns (score, best_move).
- Scores are from X's perspective: X win = +(10 - depth), O win = -(10 - depth),
  draw = 0.  Using ``depth`` makes *faster* wins worth more (depth-preferring).
"""

from functools import lru_cache

X, O, EMPTY = "X", "O", " "
EMPTY_BOARD = (EMPTY,) * 9

WIN_LINES = (
    (0, 1, 2), (3, 4, 5), (6, 7, 8),      # rows
    (0, 3, 6), (1, 4, 7), (2, 5, 8),      # columns
    (0, 4, 8), (2, 4, 6),                 # diagonals
)

INF = 100


class Counter:
    """Simple instrumentation object for counting visited search nodes."""

    def __init__(self):
        self.nodes = 0


def winner(board):
    """Return 'X' or 'O' if that player has three in a row, else None."""
    for a, b, c in WIN_LINES:
        if board[a] != EMPTY and board[a] == board[b] == board[c]:
            return board[a]
    return None


def legal_moves(board):
    return [i for i, v in enumerate(board) if v == EMPTY]


def place(board, idx, player):
    return board[:idx] + (player,) + board[idx + 1:]


def other(player):
    return O if player == X else X


def _terminal_score(winner_mark, depth):
    """Depth-preferring score: a win in fewer plies is worth more."""
    return (10 - depth) if winner_mark == X else (depth - 10)


def minimax(board, player, depth=0, counter=None):
    """Plain minimax. Returns (score from X's perspective, best_move)."""
    if counter is not None:
        counter.nodes += 1

    w = winner(board)
    if w is not None:
        return _terminal_score(w, depth), None
    moves = legal_moves(board)
    if not moves:
        return 0, None  # draw

    best_move = None
    if player == X:
        best_score = -INF
        for m in moves:
            score, _ = minimax(place(board, m, X), O, depth + 1, counter)
            if score > best_score:
                best_score, best_move = score, m
    else:
        best_score = INF
        for m in moves:
            score, _ = minimax(place(board, m, O), X, depth + 1, counter)
            if score < best_score:
                best_score, best_move = score, m
    return best_score, best_move


def alphabeta(board, player, alpha=-INF, beta=INF, depth=0, counter=None):
    """Minimax with alpha-beta pruning. Returns (score, best_move).

    Same values and move preferences as :func:`minimax`, but skips branches
    that provably cannot influence the decision at the root.
    """
    if counter is not None:
        counter.nodes += 1

    w = winner(board)
    if w is not None:
        return _terminal_score(w, depth), None
    moves = legal_moves(board)
    if not moves:
        return 0, None  # draw

    best_move = None
    if player == X:
        best_score = -INF
        for m in moves:
            score, _ = alphabeta(place(board, m, X), O,
                                 alpha, beta, depth + 1, counter)
            if score > best_score:
                best_score, best_move = score, m
            alpha = max(alpha, best_score)
            if alpha >= beta:
                break  # beta cutoff
    else:
        best_score = INF
        for m in moves:
            score, _ = alphabeta(place(board, m, O), X,
                                 alpha, beta, depth + 1, counter)
            if score < best_score:
                best_score, best_move = score, m
            beta = min(beta, best_score)
            if alpha >= beta:
                break  # alpha cutoff
    return best_score, best_move


@lru_cache(maxsize=None)
def best_move(board, player):
    """Perfect-play move for `player` from `board` (memoised alphabeta)."""
    _, move = alphabeta(board, player)
    return move
